// Goal: Map ClinicalDocument id to Composition identifier
// Use the imported II type group from at-cda-to-fhir-types so root/extension
// are translated to system/value automatically.

// XPath ClinicalDocument/id
// FHIR Path Composition.identifier


// Data Types
    // CDA: II
    // FHIR: Identifier


map "https://fhir.hl7.at/elga/cda2fhir/r4/StructureMap/ue4" = "ue4"

uses "http://hl7.org/cda/stds/core/StructureDefinition/ClinicalDocument" alias ClinicalDocument as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/II" alias II as source

uses "http://hl7.org/fhir/4.3/StructureDefinition/Bundle" alias Bundle as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Composition" alias Composition as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Identifier" alias Identifier as target



imports "http://hl7.at/fhir/HL7ATCoreProfiles/4.0.1/StructureMap/at-cda-to-fhir-types"



group MapClinicalDocumentIdToCompositionIdentifier(source cda: ClinicalDocument, target fhir_bundle: Bundle){

